import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router } from '@angular/router';
import { NotificationsService } from '../../services/notifications.service';
import { TranslationService } from '../../services/translation.service';
import { LangService } from '../../services/lang.service';
import { AuthService } from '../../services/auth.service';
import { SharedModule } from '../shared/shared.module';

enum NotificationReferenceType {
  None = 0,
  Meeting = 1,
  Task = 2,
  Visit = 3,
  Travel = 4
}

interface UserNotification {
  id: number;
  userId: string;
  notificationId: number;
  isRead: boolean;
  readAt: string | null;
}

interface Notification {
  id: number;
  title: string;
  message: string;
  type: string;
  createdAt: string;
  referenceId?: number | null;
  referenceType?: number;
  userNotifications: UserNotification[];
  isRead?: boolean;
}

@Component({
  selector: 'app-notifications',
  templateUrl: './notifications.html',
  styleUrls: ['./notifications.css'],
  standalone: true,
  imports: [
    CommonModule,
    FormsModule,
    SharedModule
  ]
})
export class NotificationsComponent implements OnInit {
  notifications: Notification[] = [];
  isLoading = false;
  currentPage = 1;
  pageSize = 10;
  totalCount = 0;
  totalPages = 0;
  searchTerm = '';
  isRTL = false;
  showNotificationModal = false;

  constructor(
    private notificationsService: NotificationsService,
    private translationService: TranslationService,
    private langService: LangService,
    private authService: AuthService,
    private router: Router
  ) {}

  ngOnInit(): void {
    this.isRTL = this.langService.isRTL();
    this.loadNotifications();
  }

  loadNotifications(): void {
    this.isLoading = true;
    this.notificationsService.getFilteredNotifications(this.currentPage, this.pageSize, this.searchTerm)
      .subscribe({
        next: (response) => {
          if (response && response.success && response.data) {
            this.notifications = response.data.items.map((notification: Notification) => {
              const currentUser = this.authService.getCurrentUser();
              const userNotification = notification.userNotifications.find(
                (un) => un.userId === currentUser?.id
              );
              return {
                ...notification,
                isRead: userNotification ? userNotification.isRead : false
              };
            });
            this.totalCount = response.data.totalCount;
            this.totalPages = Math.ceil(this.totalCount / this.pageSize);
          }
          this.isLoading = false;
        },
        error: (error) => {
          console.error('Error loading notifications:', error);
          this.isLoading = false;
        }
      });
  }

  onSearch(): void {
    this.currentPage = 1;
    this.loadNotifications();
  }

  onPageChange(page: number): void {
    if (page >= 1 && page <= this.totalPages) {
      this.currentPage = page;
      this.loadNotifications();
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  }

  getVisiblePages(): number[] {
    const maxVisible = 5;
    const pages: number[] = [];
    
    if (this.totalPages <= maxVisible) {
      // Show all pages if total is less than max
      for (let i = 1; i <= this.totalPages; i++) {
        pages.push(i);
      }
    } else {
      // Smart pagination
      const startPage = Math.max(1, this.currentPage - 2);
      const endPage = Math.min(this.totalPages, startPage + maxVisible - 1);
      
      for (let i = startPage; i <= endPage; i++) {
        pages.push(i);
      }
    }
    
    return pages;
  }

  markAsRead(notification: Notification): void {
    if (notification.isRead) return;
    
    this.notificationsService.markAsRead(notification.id).subscribe({
      next: () => {
        notification.isRead = true;
      },
      error: (error) => {
        console.error('Error marking notification as read:', error);
      }
    });
  }

  canNavigateToReference(notification: Notification): boolean {
    if (!notification.referenceType || notification.referenceType === NotificationReferenceType.None) {
      return false;
    }
    
    if (!notification.referenceId) {
      return false;
    }
    
    const requiredPermission = this.getRequiredPermission(notification.referenceType);
    if (!requiredPermission) {
      return false;
    }
    
    return this.authService.hasPermission(requiredPermission);
  }

  private getRequiredPermission(referenceType: number): string | null {
    switch (referenceType) {
      case NotificationReferenceType.Meeting:
        return 'meeting.index';
      case NotificationReferenceType.Task:
        return 'task.index';
      case NotificationReferenceType.Visit:
        return 'visits.index';
      case NotificationReferenceType.Travel:
        return 'travel.index';
      default:
        return null;
    }
  }

  navigateToReference(notification: Notification): void {
    if (!this.canNavigateToReference(notification)) {
      return;
    }
    
    if (!notification.isRead) {
      this.markAsRead(notification);
    }
    
    const referenceId = notification.referenceId;
    const referenceType = notification.referenceType;
    
    switch (referenceType) {
      case NotificationReferenceType.Meeting:
        this.router.navigate(['/meetings/details', referenceId]);
        break;
      case NotificationReferenceType.Task:
        this.router.navigate(['/tasks/details', referenceId]);
        break;
      case NotificationReferenceType.Visit:
        this.router.navigate(['/visits/details', referenceId]);
        break;
      case NotificationReferenceType.Travel:
        this.router.navigate(['/travel/details', referenceId]);
        break;
      default:
        console.warn('Unknown referenceType:', referenceType);
    }
  }

  getNotificationIcon(type: string): string {
    switch (type.toLowerCase()) {
      case 'success': return '✓';
      case 'warning': return '⚠';
      case 'error': return '✗';
      case 'reminder': return '🔔';
      case 'meeting': return '📅';
      case 'task': return '📋';
      case 'visit': return '🏢';
      case 'travel': return '✈️';
      default: return 'ℹ';
    }
  }

  getNotificationClass(type: string): string {
    return `notification-${type.toLowerCase()}`;
  }

  formatDate(dateString: string): string {
    const now = new Date();
    
    // Parse the date string and treat it as UTC if it doesn't have timezone info
    const dateStr = dateString.includes('Z') || dateString.includes('+') || dateString.includes('-', 10) 
      ? dateString 
      : dateString + 'Z';
    const date = new Date(dateStr);
    
    // Check if date is valid
    if (isNaN(date.getTime())) {
      return dateString;
    }
    
    const diffInMs = now.getTime() - date.getTime();
    const diffInSeconds = Math.floor(diffInMs / 1000);
    const diffInMinutes = Math.floor(diffInSeconds / 60);
    const diffInHours = Math.floor(diffInMinutes / 60);
    const diffInDays = Math.floor(diffInHours / 24);

    if (diffInSeconds < 30) return this.translate('notifications.justNow');
    if (diffInMinutes < 1) return this.translate('notifications.justNow');
    if (diffInMinutes < 60) return `${diffInMinutes} ${this.translate('notifications.minutesAgo')}`;
    if (diffInHours < 24) return `${diffInHours} ${this.translate('notifications.hoursAgo')}`;
    if (diffInDays < 7) return `${diffInDays} ${this.translate('notifications.daysAgo')}`;
    
    return date.toLocaleDateString(this.isRTL ? 'ar-EG' : 'en-US');
  }

  translate(key: string): string {
    return this.translationService.translate(key);
  }

  openNotificationModal(): void {
    this.showNotificationModal = true;
  }

  closeNotificationModal(): void {
    this.showNotificationModal = false;
  }

  onSendNotification(notification: any): void {
    // Handle notification sending - reload notifications after sending
    this.loadNotifications();
    this.closeNotificationModal();
  }
}
